import sqlite3
import sys

def lookup_user(username):
    """Query user profile from database."""
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    # Direct string concatenation for the CTF challenge
    query = "SELECT id, email, role FROM users WHERE username = '" + username + "'"
    cursor.execute(query)

    result = cursor.fetchone()
    conn.close()

    if result:
        return {'id': result[0], 'email': result[1], 'role': result[2]}
    else:
        return None

if __name__ == '__main__':
    if len(sys.argv) > 1:
        user_input = sys.argv[1]
        user_data = lookup_user(user_input)
        if user_data:
            print(f"Found user: {user_data}")
        else:
            print("User not found")
    else:
        print("Usage: python script.py <username>")
